<?php
declare(strict_types=1);
namespace Liberu\ControlPanel\ApiAutomationFilament\Resources;
use Filament\Resources\Resource; use Filament\Schemas\Schema; use Filament\Tables\Columns\TextColumn; use Filament\Tables\Table; use Illuminate\Database\Eloquent\Builder; use Liberu\ControlPanel\ApiAutomation\Models\AutomationCommand;
final class AutomationCommandResource extends Resource { protected static ?string $model=AutomationCommand::class; protected static string|\BackedEnum|null $navigationIcon='heroicon-o-command-line'; protected static string|\UnitEnum|null $navigationGroup='Control Panel'; public static function form(Schema $schema):Schema{return $schema->components([]);} public static function table(Table $table):Table{return $table->columns([TextColumn::make('name')->searchable()->sortable(),TextColumn::make('command'),TextColumn::make('enabled')->badge(),TextColumn::make('last_run_at')->dateTime()])->defaultSort('created_at','desc');} public static function getEloquentQuery():Builder{return parent::getEloquentQuery()->where('team_id',auth()->user()?->current_team_id);} public static function getPages():array{return ['index'=>Pages\ListAutomationCommands::route('/')];} }
